package com.aliothmoon.maafw.once;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NativeUiBoundPointsParserTest {
 static String text(boolean search,String middle,String n,String d){return(search?"搜索以赚取":"阅读以赚取")+", "+middle+", 已赚取 "+n+" 积分(需要 "+d+" 积分)";}
 static NativeUiBoundPointsParser.Node n(int i,int parent,String id,String text,int top,int bottom){return new NativeUiBoundPointsParser.Node(i,parent,true,true,id,text,null,0,top,1000,bottom);}
 static List<NativeUiBoundPointsParser.Node> tree(){return new ArrayList<>(List.of(n(0,-1,"root",null,0,2000),n(1,0,"homePageWrapper",null,0,2000),n(2,1,"dailyTaskPanel",null,0,2000),n(3,2,"dailyActivities",null,0,2000),n(4,3,"search",null,0,900),n(5,3,"read",null,1000,1900)));}
 static NativeUiBoundPointsParser.Node copy(NativeUiBoundPointsParser.Node n,boolean visible,String description){return new NativeUiBoundPointsParser.Node(n.index(),n.parentIndex(),visible,n.packageMatches(),n.resourceId(),n.text(),description,n.left(),n.top(),n.right(),n.bottom());}
 static NativeUiStructureParser.Result parse(String search,String read){var t=tree();if(search!=null)t.add(n(6,4,null,search,100,300));if(read!=null)t.add(n(7,5,null,read,1100,1300));return NativeUiBoundPointsParser.parse(t);}
 static void status(NativeUiStructureParser.Status wanted,NativeUiStructureParser.TaskResult r){assertEquals(wanted,r.status());if(wanted!=NativeUiStructureParser.Status.KNOWN)assertEquals(NativeUiStructureParser.Unit.UNESTABLISHED,r.unit());}
 static void known(NativeUiStructureParser.TaskResult r,int n,int d){status(NativeUiStructureParser.Status.KNOWN,r);assertEquals(n,r.current());assertEquals(d,r.target());assertEquals(1,r.matchCount());}
 @Test public void exactBoundFieldsReadIndependently(){var x=parse(text(true,"使用必应搜索赚取奖励积分","0","60"),text(false,"阅读新闻赚取奖励积分","0","30"));known(x.search(),0,60);known(x.reading(),0,30);assertFalse(x.actionAuthority());}
 @Test public void ordinaryPointsWordsInNondigitMiddleAllowed(){known(parse(null,text(false,"通过阅读赚取奖励积分","1","30")).reading(),1,30);}
 @Test public void middleLettersAndSpacesOnlyNoAllSpaces(){known(parse(text(true,"Search in Bing","1","60"),null).search(),1,60);for(String m:new String[]{""," ","   ","x".repeat(129),"阅读1次","阅读１次","阅读٢次","阅读Ⅲ次","阅读一遍","阅读〇遍","阅读两遍","阅读,新闻","阅读/新闻","阅读(新闻)","阅读\n新闻","阅读\t新闻","已赚取奖励","需要阅读"})status(NativeUiStructureParser.Status.INVALID,parse(null,text(false,m,"0","30")).reading());}
 @Test public void explicitAsciiUnsignedOnly(){for(String x:new String[]{"+1","-1","1.0","１","٢","10001","999999999999999999999"})status(NativeUiStructureParser.Status.INVALID,parse(text(true,"搜索奖励",x,"10000"),null).search());for(String x:new String[]{"0","-1","+30","10001"})status(NativeUiStructureParser.Status.INVALID,parse(null,text(false,"阅读奖励","0",x)).reading());}
 @Test public void boundsAndCompletion(){known(parse(text(true,"搜索奖励","10000","10000"),null).search(),10000,10000);status(NativeUiStructureParser.Status.INVALID,parse(null,text(false,"阅读奖励","31","30")).reading());}
 @Test public void noTargetInferenceOrFractionJoining(){status(NativeUiStructureParser.Status.INVALID,parse("搜索以赚取, 搜索奖励, 已赚取 60 积分",null).search());var t=tree();t.add(n(6,5,null,"阅读以赚取",1100,1200));t.add(n(7,5,null,"0/30",1200,1300));status(NativeUiStructureParser.Status.UNKNOWN,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void exactPunctuationSpacingAndWholeField(){String good=text(false,"阅读奖励","0","30");for(String x:new String[]{good+"\n",good+" ",good.replace(",","，"),good.replace("已赚取 0","已赚取0"),good.replace("(需要","（需要"),"prefix "+good})assertNotEquals(NativeUiStructureParser.Status.KNOWN,parse(null,x).reading().status());}
 @Test public void equalTextDescriptionDedup(){var t=tree();var row=n(6,5,null,text(false,"阅读奖励","0","30"),1100,1200);t.add(copy(row,true,row.text()));known(NativeUiBoundPointsParser.parse(t).reading(),0,30);}
 @Test public void duplicateNodesAndDistinctFieldsAmbiguous(){String a=text(false,"阅读奖励","0","30");var t=tree();t.add(n(6,5,null,a,1100,1200));t.add(n(7,5,null,a,1200,1300));status(NativeUiStructureParser.Status.AMBIGUOUS,NativeUiBoundPointsParser.parse(t).reading());t=tree();t.add(copy(n(6,5,null,a,1100,1200),true,text(false,"阅读奖励","1","30")));status(NativeUiStructureParser.Status.AMBIGUOUS,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void hiddenCandidateStillConflicts(){String a=text(false,"阅读奖励","0","30");var t=tree();t.add(n(6,5,null,a,1100,1200));t.add(copy(n(7,5,null,a,1200,1300),false,null));status(NativeUiStructureParser.Status.AMBIGUOUS,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void soleHiddenAndNestedNeverKnown(){String a=text(false,"阅读奖励","0","30");var t=tree();t.add(copy(n(6,5,null,a,1100,1200),false,null));status(NativeUiStructureParser.Status.UNKNOWN,NativeUiBoundPointsParser.parse(t).reading());t=tree();t.add(n(6,5,null,null,1100,1500));t.add(n(7,6,null,a,1200,1300));status(NativeUiStructureParser.Status.UNKNOWN,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void oppositeSummaryInvalidatesWholeObservation(){var x=parse(text(false,"阅读奖励","0","30"),text(false,"阅读奖励","0","30"));status(NativeUiStructureParser.Status.INVALID,x.search());status(NativeUiStructureParser.Status.INVALID,x.reading());}
 @Test public void hiddenOppositeAndMalformedStillHold(){var t=tree();t.add(copy(n(6,5,null,text(true,"搜索奖励","0","60"),1100,1200),false,null));status(NativeUiStructureParser.Status.INVALID,NativeUiBoundPointsParser.parse(t).reading());t=tree();t.add(copy(n(6,5,null,"阅读以赚取, wrong",1100,1200),false,null));status(NativeUiStructureParser.Status.INVALID,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void noProximityAssociation(){var t=tree();t.add(n(6,3,null,text(false,"阅读奖励","0","30"),1100,1200));status(NativeUiStructureParser.Status.UNKNOWN,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void candidateMustFitItsCard(){var t=tree();t.add(n(6,5,null,text(false,"阅读奖励","0","30"),800,1200));status(NativeUiStructureParser.Status.INVALID,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void duplicateOrMissingOrWrongCaseResourceInvalidatesBoth(){for(int mode=0;mode<3;mode++){var t=tree();if(mode==0)t.add(n(6,3,"read",null,1000,1900));if(mode==1)t.remove(5);if(mode==2)t.set(5,n(5,3,"Read",null,1000,1900));bothInvalid(t);}}
 @Test public void hierarchyMustUseActualDirectParents(){var t=tree();t.set(5,n(5,2,"read",null,1000,1900));bothInvalid(t);}
 @Test public void hiddenOrEmptyHierarchyRejected(){var t=tree();t.set(5,copy(t.get(5),false,null));bothInvalid(t);t=tree();t.set(5,n(5,3,"read",null,1000,1000));bothInvalid(t);}
 @Test public void invalidShapeCannotYieldOneKnown(){bothInvalid(null);bothInvalid(List.of());var t=tree();t.add(null);bothInvalid(t);t=tree();t.add(n(5,3,null,null,100,200));bothInvalid(t);t=tree();t.add(n(7,99,null,null,100,200));bothInvalid(t);t=tree();t.add(n(7,-1,null,null,100,200));bothInvalid(t);t=tree();t.add(new NativeUiBoundPointsParser.Node(7,5,true,false,null,text(false,"阅读奖励","0","30"),null,0,1100,1000,1200));bothInvalid(t);}
 @Test public void shapeLimitsNodeDepthFieldAndBatch(){var t=tree();for(int i=6;i<513;i++)t.add(n(i,0,null,null,100,200));bothInvalid(t);t=tree();t.add(n(6,0,null,"x".repeat(2049),100,200));bothInvalid(t);t=tree();for(int i=6;i<23;i++)t.add(n(i,0,null,"x".repeat(2048),100,200));bothInvalid(t);t=tree();for(int i=6;i<40;i++)t.add(n(i,i==6?5:i-1,null,null,1100,1200));bothInvalid(t);}
 static void bothInvalid(List<NativeUiBoundPointsParser.Node> t){var r=NativeUiBoundPointsParser.parse(t);status(NativeUiStructureParser.Status.INVALID,r.search());status(NativeUiStructureParser.Status.INVALID,r.reading());}
 @Test public void prefixedTitleConflictNeverIgnoredBesideClean(){String good=text(false,"阅读奖励","0","30");for(String prefix:new String[]{" ","\t","\n","\r","\u00a0","\ufeff","\u200b","\u0001"}){var t=tree();t.add(n(6,5,null,good,1100,1200));t.add(copy(n(7,5,null,prefix+good,1200,1300),false,null));status(NativeUiStructureParser.Status.INVALID,NativeUiBoundPointsParser.parse(t).reading());}}
 @Test public void cardContainerIsConflictEvidenceNotCounterAuthority(){String good=text(false,"阅读奖励","0","30");var t=tree();t.set(5,n(5,3,"read",good,1000,1900));status(NativeUiStructureParser.Status.UNKNOWN,NativeUiBoundPointsParser.parse(t).reading());t.add(n(6,5,null,good,1100,1200));status(NativeUiStructureParser.Status.AMBIGUOUS,NativeUiBoundPointsParser.parse(t).reading());t=tree();t.set(5,n(5,3,"read",text(true,"搜索奖励","0","60"),1000,1900));status(NativeUiStructureParser.Status.INVALID,NativeUiBoundPointsParser.parse(t).reading());}
 @Test public void exactBareOtherTitleIsNotASummary(){var t=tree();t.add(n(6,4,null,"阅读以赚取",100,200));t.add(n(7,5,null,text(false,"阅读奖励","0","30"),1100,1200));var x=NativeUiBoundPointsParser.parse(t);status(NativeUiStructureParser.Status.UNKNOWN,x.search());known(x.reading(),0,30);}
 @Test public void explicitChineseNumeralVariantsRejected(){for(char c:"壱壹贰貳叁參肆伍陆陸柒捌玖拾佰仟萬億亿廿卅卌兩".toCharArray())status(NativeUiStructureParser.Status.INVALID,parse(null,text(false,"阅读"+c+"次","0","30")).reading());known(parse(null,text(false,"阅读赚取奖励积分","0","30")).reading(),0,30);}
}
